-- Drop the existing stored procedure
DROP PROCEDURE logging.sp_UpdateSilverTracking;
GO

CREATE PROCEDURE logging.SP_UpdateTracking
    @trading_pair VARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TotalRowCount BIGINT;
    DECLARE @SystemUpdateTime DATETIME2;
    DECLARE @TableName VARCHAR(50) = 'crypto_candles'; 
    DECLARE @LastTimestamp DATETIME2;

    -- Get latest watermark and count from silver table
    SELECT 
        @LastTimestamp = MAX(close_timestamp),
        @TotalRowCount = COUNT(*)
    FROM silver.crypto_candles
    WHERE trading_pair = @trading_pair;

    SET @TotalRowCount = ISNULL(@TotalRowCount, 0);
    SET @SystemUpdateTime = GETUTCDATE();

    -- UPSERT logic
    IF EXISTS (
        SELECT 1 
        FROM logging.TrackingTable 
        WHERE Table_Name = @TableName 
        AND trading_pair = @trading_pair
    )
    BEGIN
        UPDATE logging.TrackingTable
        SET
            Last_Processed_Timestamp = @LastTimestamp,
            Record_Count = @TotalRowCount,
            System_Update_Time = @SystemUpdateTime,
            Full_refresh = 0  
        WHERE
            Table_Name = @TableName
            AND trading_pair = @trading_pair;
    END
    ELSE
    BEGIN
        INSERT INTO logging.TrackingTable
        (
            Table_Name,
            trading_pair,
            Last_Processed_Timestamp,
            Record_Count,
            System_Update_Time,
            Full_refresh
        )
        VALUES
        (
            @TableName,
            @trading_pair,
            @LastTimestamp,
            @TotalRowCount,
            @SystemUpdateTime,
            0
        );
    END
END;
GO

select * from silver.crypto_candles where trading_pair = 'ETCUSDT' order by close_timestamp DESC;

